import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

swish_hardswish_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

// Swish = x * sigmoid(x)
__global__ void swish_kernel(const float* inp, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = inp[idx];
        out[idx] = x / (1.0f + expf(-x));
    }
}

// HardSwish = x * ReLU6(x+3)/6
__global__ void hardswish_kernel(const float* inp, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = inp[idx];
        float relu6 = fmaxf(0.0f, fminf(x + 3.0f, 6.0f));
        out[idx] = x * relu6 / 6.0f;
    }
}

torch::Tensor swish_cuda(torch::Tensor input) {
    auto out = torch::zeros_like(input);
    int size = input.numel();
    int block_size = 256;
    int grid_size = (size + block_size - 1) / block_size;
    swish_kernel<<<grid_size, block_size>>>(input.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}

torch::Tensor hardswish_cuda(torch::Tensor input) {
    auto out = torch::zeros_like(input);
    int size = input.numel();
    int block_size = 256;
    int grid_size = (size + block_size - 1) / block_size;
    hardswish_kernel<<<grid_size, block_size>>>(input.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}
"""

swish_hardswish_cpp_source = r"""
torch::Tensor swish_cuda(torch::Tensor input);
torch::Tensor hardswish_cuda(torch::Tensor input);
"""

swish_hardswish = load_inline(
    name="swish_hardswish",
    cpp_sources=swish_hardswish_cpp_source,
    cuda_sources=swish_hardswish_source,
    functions=["swish_cuda", "hardswish_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized Model that performs a 3D transposed convolution, uses a custom Swish, 
    group normalization, and then a custom HardSwish activation.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, groups, eps, bias=True):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(
            in_channels, 
            out_channels, 
            kernel_size, 
            stride=stride, 
            padding=padding, 
            bias=bias
        )
        self.group_norm = nn.GroupNorm(num_groups=groups, num_channels=out_channels, eps=eps)
        self.swish_mod = swish_hardswish
        self.hardswish_mod = swish_hardswish

    def forward(self, x):
        x = self.conv_transpose(x)
        # Swish via custom CUDA
        x = self.swish_mod.swish_cuda(x)
        x = self.group_norm(x)
        # HardSwish via custom CUDA
        x = self.hardswish_mod.hardswish_cuda(x)
        return x

